    type: "historical",
    parent: "MA-03",
    coords: [-4.973, 34.064],
    name: {
      de: "Al-Qarawiyyin",
      hu: "Al-Qarawiyyin",
      ro: "Al-Qarawiyyin",
      en: "Al-Qarawiyyin"},
    descriptionAdvanced: {
      de: "Die Al-Qarawiyyin-Moschee und Universität in Fès gilt als die älteste kontinuierlich betriebene Bildungseinrichtung der Welt. Sie wurde im Jahr 859 von Fatima al-Fihri gegründet, einer gebildeten Erbin, die ihr Vermögen dem Bau eines religiösen und intellektuellen Zentrums widmete. Ursprünglich als Moschee konzipiert, entwickelte sich der Komplex schnell zu einem bedeutenden Ort für islamische Wissenschaften und Rechtswissenschaft. Unter der Almoraviden-Dynastie im 12. Jahrhundert erfuhr das Bauwerk massive Erweiterungen, die ihm sein heutiges architektonisches Gepräge mit über 200 Säulen und prächtigen Bögen verliehen. Die angeschlossene Bibliothek, die im 14. Jahrhundert von Sultan Abu Inan Faris formalisiert wurde, beherbergt Tausende seltener Manuskripte. Das Institut war über Jahrhunderte ein geistiger Treffpunkt für Gelehrte wie Ibn Chaldun und Maimonides. Heute ist die Al-Qarawiyyin sowohl ein spirituelles Zentrum als auch ein UNESCO-Weltkulturerbe, das bis zu 22.000 Gläubige aufnehmen kann.",
      hu: "A fezi al-Karavijjín mecset és egyetem a világ legrégebbi, folyamatosan működő felsőoktatási intézményeként ismert. Az intézményt 859-ben alapította Fatima al-Fihri, egy jómódú örökösnő, aki vagyonát egy közösségi vallási és tanulmányi központ létrehozására fordította. Az eredetileg mecsetként induló komplexum hamar az iszlám tudományok és a jogtudomány egyik legfontosabb központjává vált. Az Almoravida dinasztia idején, a 12. században jelentős bővítéseken ment keresztül, ekkor nyerte el mai építészeti formáját a 270 oszloppal és díszes boltívekkel. A 14. században Abu Inan Faris szultán által alapított könyvtár ma is több ezer ritka kéziratot őriz. Az egyetem évszázadokon át olyan híres tudósoknak adott otthont, mint Ibn Khaldún és Maimonidész. Napjainkban az épületegyüttes az UNESCO Világörökség része, és egyszerre szolgál spirituális központként és akadémiai intézményként, befogadóképessége eléri a 22 000 főt.",
      ro: "Moscheea și Universitatea Al-Qarawiyyin din Fes este recunoscută drept cea mai veche instituție de învățământ superior din lume care funcționează neîntrerupt. Fondată în anul 859 de către Fatima al-Fihri, o moștenitoare educată, aceasta a fost inițial o moschee care s-a transformat rapid într-un centru major de studii islamice. Sub dinastia Almoravidă, în secolul al XII-lea, complexul a beneficiat de extinderi masive, primind arhitectura sa actuală caracterizată prin cele 270 de coloane și arcadele bogat decorate. Biblioteca universității, oficializată în secolul al XIV-lea de sultanul Abu Inan Faris, adăpostește mii de manuscrise rare de o valoare inestimabilă. De-a lungul secolelor, a servit drept punte intelectuală între lumea islamică și Europa, găzduind savanți renumiți precum Ibn Khaldun și Maimonides. Astăzi, situl este inclus în Patrimoniul Mondial UNESCO și rămâne un pilon al identității spirituale și academice a Marocului, având o capacitate de peste 22.000 de pelerini.",
      en: "The Al-Qarawiyyin Mosque and University in Fez is recognized as the oldest continuously operating, degree-granting educational institution in the world. Founded in 859 AD by Fatima al-Fihri, a wealthy heiress, it originally served as a mosque before evolving into a preeminent center of Islamic learning and law. The complex underwent major expansions under the Almoravid dynasty in 1135, which established much of its current architectural layout featuring 270 pillars and intricate archways. The university's library, formalized in the 14th century by Sultan Abu Inan Faris, remains one of the oldest and most significant in the world, housing thousands of rare manuscripts. For centuries, it served as a vital intellectual hub, hosting renowned scholars such as Ibn Khaldun and the philosopher Maimonides. Today, the site is a UNESCO World Heritage landmark and continues to function as a spiritual center, capable of accommodating over 22,000 worshippers.",
      es: "Al-Qarawiyyin es un elemento notable de la geografía y cultura marroquí. Considerada la universidad en funcionamiento continuo más antigua del mundo. Fue fundada en 859 por Fátima al-Fihri y es uno de los centros espirituales y educativos más importantes del mundo islámico. Fundada en el año 859. Se encuentra en el corazón de la medina de Fez. Este lugar tiene una importancia especial en la historia de Marruecos. Al igual que muchos lugares significativos en Marruecos, este sitio combina peculiaridades regionales e importancia general, contribuyendo al perfil polifacético de Marruecos.",
      pt: "Al-Qarawiyyin é um elemento notável da geografia e cultura marroquina. Considerada a universidade em funcionamento contínuo mais antiga do mundo. Foi fundada em 859 por Fátima al-Fihri e é um dos centros espirituais e educativos mais importantes do mundo islâmico. Fundada no ano 859. Localiza-se no coração da medina de Fez. Este local tem uma importância especial na história de Marrocos. Como muitos locais significativos em Marrocos, este local combina peculiaridades regionais e importância abrangente, contribuindo para o perfil multifacetado de Marrocos.",
      fr: "Al-Qarawiyyin est un élément remarquable de la géographie et de la culture marocaines. Considérée comme la plus ancienne université au monde encore en activité. Elle a été fondée en 859 par Fatima al-Fihri et est l'un des centres spirituels et éducatifs les plus importants du monde islamique. Fondée en 859. Située au cœur de la médina de Fès. Ce lieu revêt une importance particulière dans l'histoire du Maroc. Comme beaucoup de lieux importants au Maroc, ce site réunit des particularités régionales et une importance globale, contribuant ainsi au profil diversifié du Maroc.",
    },
