      hu: ["859-ben alapította Fatima al-Fihri.", "A világ legrégebbi egyeteme a Guinness Rekordok Könyve szerint.", "Körülbelül 22 000 hívő befogadására alkalmas.", "A könyvtárat hivatalosan 1349-ben alapították.", "1981-ben vált az UNESCO Világörökség részévé Fez medinájával együtt.", "Több mint 4000 ritka középkori kéziratot őriznek itt."],
      ro: ["Fondată în anul 859 de către Fatima al-Fihri.", "Cea mai veche universitate din lume conform Guinness World Records.", "Capacitate de aproximativ 22.000 de persoane pentru rugăciune.", "Biblioteca a fost stabilită oficial în anul 1349.", "Inclusă în Patrimoniul Mondial UNESCO în 1981.", "Adăpostește peste 4.000 de manuscrise medievale rare."],
      en: ["Founded in 859 AD by Fatima al-Fihri.", "Oldest university in the world according to Guinness World Records.", "Accommodates approximately 22,000 worshippers for prayer.", "The library was officially established in 1349.", "Designated a UNESCO World Heritage site in 1981.", "Houses more than 4,000 rare medieval manuscripts."],
      es: ["Considerada la universidad en funcionamiento continuo más antigua del mundo. Fue fundada en 859 por Fátima al-Fihri y es uno de los centros espirituales y educativos más importantes del mundo islámico.", "Se encuentra en el territorio del Reino de Marruecos.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural.", "Está documentado en estudios locales y regionales."],
      pt: ["Considerada a universidade em funcionamento contínuo mais antiga do mundo. Foi fundada em 859 por Fátima al-Fihri e é um dos centros espirituais e educativos mais importantes do mundo islâmico.", "Localiza-se no território do Reino de Marrocos.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural.", "Está documentado em estudos locais e regionais."],
      fr: ["Considérée comme la plus ancienne université au monde encore en activité. Elle a été fondée en 859 par Fatima al-Fihri et est l'un des centres spirituels et éducatifs les plus importants du monde islamique.", "Situé sur le territoire du Royaume du Maroc.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle.", "Documenté dans des études locales et régionales."],
