    type: "historical",
    parent: "MA-03",
    coords: [-4.982, 34.062],
    name: {
      de: "Medersa Bou Inania",
      hu: "Bou Inania madrasza",
      ro: "Medersa Bou Inania",
      en: "Bou Inania Madrasa"},
    descriptionAdvanced: {
      de: "Die Medersa Bou Inania in Fès ist eines der herausragendsten Bauwerke der Meriniden-Architektur in Marokko. Sie wurde zwischen 1350 und 1355 von Sultan Abu Inan Faris erbaut. Das Besondere an dieser Madrasa ist, dass sie nicht nur als theologische Schule diente, sondern auch als Freitagsmoschee fungierte, was durch ihr prachtvolles Minaret deutlich wird. Die Architektur zeichnet sich durch eine unglaubliche Detailtiefe aus: geschnitztes Zedernholz, fein gearbeiteter Stuck und komplexe Zellige-Mosaike bedecken fast jede Oberfläche des zentralen Hofes. Ein kleiner Bach fließt durch den Hof und diente ursprünglich rituellen Waschungen. Gegenüber der Madrasa befindet sich die berühmte Wasseruhr Dar al-Magana, die ebenfalls aus der Merinidenzeit stammt. Die Bou Inania wurde im 18. und 20. Jahrhundert umfassend restauriert und gilt heute als eines der wenigen religiösen Gebäude in Marokko, das auch von Nicht-Muslimen betreten werden darf.",
      hu: "A fezi Bou Inania medresze a merinida építészet egyik legkiemelkedőbb alkotása Marokkóban. 1350 és 1355 között építtette Abu Inan Faris szultán. E medresze különlegessége, hogy nemcsak teológiai iskolaként szolgált, hanem pénteki mecsetként is funkcionált, amit díszes minaretje is jelez. Az építészetet a részletek hihetetlen gazdagsága jellemzi: faragott cédrusfa, finoman kidolgozott stukkó és összetett zellige mozaikok borítják a központi udvar szinte minden felületét. Az udvaron egy kis patak folyik keresztül, amely eredetileg rituális mosakodásra szolgált. A medreszével szemben található a híres Dar al-Magana vízi óra, amely szintén a merinida korból származik. A Bou Inaniát a 18. és a 20. században jelentősen restaurálták, és ma azon kevés vallási épületek egyike Marokkóban, amelyet nem muszlimok is látogathatnak.",
      ro: "Medersa Bou Inania din Fes este una dintre cele mai remarcabile structuri ale arhitecturii merinide din Maroc. A fost construită între anii 1350 și 1355 de sultanul Abu Inan Faris. Particularitatea acestei madrasa este că nu a servit doar ca școală teologică, ci a funcționat și ca moschee de vineri, fapt evidențiat de minaretul său splendid. Arhitectura se caracterizează printr-o profunzime incredibilă a detaliilor: lemn de cedru sculptat, stuc fin prelucrat și mozaicuri complexe zellige acoperă aproape fiecare suprafață a curții centrale. Un mic pârâu curge prin curte, servind inițial pentru spălările rituale. Vizavi de madrasa se află celebrul ceas cu apă Dar al-Magana, care datează tot din perioada merinidă. Bou Inania a fost restaurată extensiv în secolele XVIII și XX și este astăzi una dintre puținele clădiri religioase din Maroc care pot fi vizitate de non-musulmani.",
      en: "The Bou Inania Madrasa in Fez is one of the most outstanding examples of Marinid architecture in Morocco. It was built between 1350 and 1355 AD by Sultan Abu Inan Faris. A unique feature of this madrasa is that it served not only as a theological college but also functioned as a Friday mosque, as evidenced by its magnificent minaret. The architecture is characterized by an incredible depth of detail, with carved cedar wood, finely worked stucco, and complex zellige mosaics covering nearly every surface of the central courtyard. A small stream flows through the courtyard, originally used for ritual ablutions. Opposite the madrasa stands the famous Dar al-Magana water clock, which also dates from the Marinid era. Bou Inania underwent extensive restorations in the 18th and 20th centuries and is today one of the few religious buildings in Morocco open to non-Muslim visitors.",
      es: "La Medersa Bou Inania es un elemento notable de la geografía y cultura marroquíes. Esta escuela teológica en Fez, fundada en el siglo XIV, destaca por ser uno de los pocos edificios religiosos accesibles para no musulmanes. Es una obra maestra de la arquitectura meriní y cuenta con un singular reloj de agua. El sitio tiene una relevancia especial en la historia de Marruecos, integrando particularidades regionales con una importancia nacional que enriquece el perfil del país.",
      pt: "A Medersa Bou Inania é um elemento notável da geografia e cultura marroquinas. Uma escola teológica em Fez, fundada no século XIV. É um dos poucos edifícios religiosos em Marrocos acessível a não muçulmanos. É considerada uma obra-prima da arquitetura merínida e possui um relógio de água. Este local tem uma importância especial na história de Marrocos, unindo peculiaridades regionais com uma relevância nacional, contribuindo para o perfil diversificado do país.",
      fr: "La Médersa Bou Inania est un élément remarquable de la géographie et de la culture marocaines. Cette école théologique de Fès, fondée au XIVe siècle, est l'un des rares édifices religieux du Maroc accessibles aux non-musulmans. Chef-d'œuvre de l'architecture mérinide, elle possède une horloge hydraulique unique. Ce lieu revêt une importance particulière dans l'histoire du Maroc, alliant spécificités régionales et portée nationale, contribuant ainsi au profil diversifié du pays.",
    },
    factsAdvanced: {
      de: ["Erbaut zwischen 1350 und 1355 von Sultan Abu Inan Faris.", "Einzige Madrasa in Fès mit einem eigenen Minaret.", "Dient sowohl als Schule als auch als offizielle Freitagsmoschee.", "Die gegenüberliegende Wasseruhr Dar al-Magana stammt von 1357.", "Die Zedernholzschnitzereien gelten als Meisterwerke der Meriniden.", "Zählt zu den wenigen Moscheen, die Nicht-Muslime betreten dürfen."],
      hu: ["1350 és 1355 között építette Abu Inan Faris szultán.", "Az egyetlen medresze Fezben, amely saját minarettel rendelkezik.", "Egyszerre szolgál iskolaként és hivatalos pénteki mecsetként.", "A szemközti Dar al-Magana vízi óra 1357-ből származik.", "A cédrusfa faragványokat a merinida művészet remekműveinek tartják.", "Azon kevés mecsetek egyike, ahová nem muszlimok is beléphetnek."],
      ro: ["Construită între 1350 și 1355 de sultanul Abu Inan Faris.", "Singura madrasa din Fes care are propriul minaret.", "Servește atât ca școală, cât și ca moschee oficială de vineri.", "Ceasul cu apă Dar al-Magana de vizavi datează din 1357.", "Sculpturile în lemn de cedru sunt capodopere ale artei merinide.", "Este una dintre puținele moschei în care pot intra non-musulmanii."],
      en: ["Built between 1350 and 1355 by Sultan Abu Inan Faris.", "The only madrasa in Fez to feature its own minaret.", "Functions as both an educational college and a Friday mosque.", "The Dar al-Magana water clock opposite was completed in 1357.", "The cedar wood carvings are masterpieces of Marinid art.", "One of the few religious sites in Morocco open to non-Muslims."],
      es: ["Una escuela teológica en Fez fundada en el siglo XIV.", "Es una de las pocas mezquitas abiertas a no musulmanes.", "Destaca por su refinada arquitectura meriní.", "La Medersa Bou Inania se encuentra en Marruecos."],
      pt: ["Uma escola teológica em Fez fundada no século XIV.", "É um dos poucos edifícios religiosos abertos a não muçulmanos.", "Destaca-se pela sua arquitetura merínida refinada.", "A Medersa Bou Inania está localizada em Marrocos."],
      fr: ["Une école théologique à Fès fondée au XIVe siècle.", "C'est l'un des rares édifices religieux ouverts aux non-musulmans.", "Elle se distingue par son architecture mérinide raffinée.", "La Médersa Bou Inania est située au Maroc."],
    },
