      hu: "A 14. században alapított teológiai főiskola Fesben. Az egyetlen olyan vallási épületek egyike Marokkóban, amely nem muszlimok számára is látogatható.",
      ro: "Un colegiu teologic în Fes, fondat în secolul al XIV-lea. Este una dintre puținele clădiri religioase din Maroc deschise și non-musulmanilor.",
      en: "A theological college in Fes founded in the 14th century. It is one of the few religious buildings in Morocco that is also open to non-Muslims.",
      es: "Una escuela teológica en Fez fundada en el siglo XIV. Es uno de los pocos edificios religiosos en Marruecos que está abierto a los no musulmanes.",
      pt: "Uma escola teológica em Fez fundada no século XIV. É um dos poucos edifícios religiosos em Marrocos que está aberto a não muçulmanos.",
      fr: "Une école théologique à Fès fondée au XIVe siècle. C'est l'un des rares édifices religieux du Maroc à être ouvert aux non-musulmans.",
