      en: ["Founded in the 12th century by the Almohad dynasty.", "The monumental Bab Oudaia gate was completed around 1195.", "Contains Rabat's oldest mosque, dating back to roughly 1150.", "Served as a pirate stronghold for the 'Salé Rovers' in the 17th century.", "Listed as a UNESCO World Heritage site in 2012.", "The Andalusian Gardens were added in the early 20th century."],
      es: ["La primera piedra fue colocada en el siglo XII por la dinastía almohade.", "El nombre proviene de la tribu Oudayas, que se estableció aquí en el siglo XIX.", "La gran puerta, Bab Oudaia, fue construida alrededor de 1195.", "El color azul y blanco fue introducido por los refugiados andaluces.", "El Jardín Andaluz fue creado durante la época colonial francesa.", "Dentro de la Kasbah se encuentra la mezquita más antigua de Rabat, la Jama al-Atiqa.", "La fortaleza servía para proteger contra los ataques piratas.", "La plataforma 'Plateforme du Sémaphore' ofrece las mejores vistas del Atlántico."],
      pt: ["A primeira pedra foi lançada no século XII pela dinastia almoada.", "O nome provém da tribo Oudayas, que foi estacionada aqui no século XIX.", "A grande porta, Bab Oudaia, foi construída por volta de 1195.", "A coloração azul e branca foi introduzida pelos refugiados andaluzes.", "O Jardim Andaluz foi criado durante o período colonial francês.", "Dentro da Kasbah encontra-se a mesquita mais antiga de Rabat, a Jama al-Atiqa.", "A fortaleza servia de proteção contra ataques de piratas.", "A plataforma 'Plateforme du Sémaphore' oferece a melhor vista sobre o Atlântico."],
      fr: ["La première pierre fut posée au XIIe siècle par la dynastie almohade.", "Le nom vient de la tribu des Oudayas, qui fut stationnée ici au XIXe siècle.", "La grande porte, Bab Oudaia, a été construite vers 1195.", "Les couleurs bleu et blanc ont été introduites par les réfugiés andalous.", "Le jardin andalou a été aménagé pendant la période coloniale française.", "À l'intérieur de la Kasbah se trouve la plus ancienne mosquée de Rabat, la Jama al-Atiqa.", "La forteresse servait à se protéger des attaques de pirates.", "La 'Plateforme du Sémaphore' offre la meilleure vue sur l'Atlantique."],
