      de: "Der offizielle Sitz des Königs von Marokko. Der weitläufige Palastkomplex in der Hauptstadt Rabat beeindruckt durch seine massiven Tore und die bewachte Paradefläche.",
      hu: "Marokkó királyának hivatalos rezidenciája. A fővárosban, Rabatban található hatalmas palotakomplexum lenyűgöző hatalmas kapuival és őrzött parádés terével.",
      ro: "Reședința oficială a regelui Marocului. Complexul palatului din capitala Rabat impresionează prin porțile sale masive.",
      en: "The official residence of the King of Morocco. The expansive palace complex in the capital Rabat impresses with its massive gates and guarded parade ground.",
      es: "La sede oficial del Rey de Marruecos. El extenso complejo palaciego en la capital, Rabat, impresiona con sus puertas macizas y la explanada de desfiles vigilada.",
      pt: "A sede oficial do Rei de Marrocos. O vasto complexo palaciano na capital, Rabat, impressiona pelas suas portas maciças e pela praça de desfiles vigiada.",
      fr: "Le siège officiel du roi du Maroc. Ce vaste complexe palatial situé dans la capitale, Rabat, impressionne par ses portes massives et son esplanade de parade gardée.",
