    facts: {
      de: ["Erbaut zwischen 1961 und 1971", "Gegenüber dem berühmten Hassan-Turm"],
      hu: ["1961 és 1971 között épült", "A híres Hasszán-toronnyal szemben áll"],
      ro: ["Construit între 1961 și 1971", "Situat vizavi de faimosul Turn Hassan"],
      en: ["Built between 1961 and 1971", "Located opposite the famous Hassan Tower"],
      es: ["Construido entre 1961 y 1971", "Frente a la famosa Torre Hassan"],
      pt: ["Construído entre 1961 e 1971", "Em frente à famosa Torre Hassan"],
      fr: ["Construit entre 1961 et 1971", "Face à la célèbre tour Hassan"],
    },
    descriptionAdvanced: {
      de: "Das Mausoleum von Mohammed V. in Rabat ist ein architektonisches Meisterwerk und eine bedeutende nationale Gedenkstätte Marokkos. Es wurde zwischen 1961 und 1971 errichtet und beherbergt die Gräber von König Mohammed V. sowie seiner Söhne Hassan II. und Prinz Abdallah. Der Bau wurde vom vietnamesischen Architekten Eric Vo Toan entworfen und kombiniert traditionelle marokkanische Kunstfertigkeit mit modernen Bautechniken. Das Äußere ist aus strahlend weißem italienischem Marmor gefertigt und wird von einem markanten grünen Ziegeldach gekrönt, der Farbe des Islams. Im Inneren beeindruckt die prächtige Kuppel aus Zedernholz mit Blattgoldverzierungen und die Wände sind mit feinsten Zellige-Mosaiken bedeckt. Das Mausoleum befindet sich auf der Esplanade des unvollendeten Hassan-Turms und bildet zusammen mit diesem ein monumentales Ensemble. Es ist ein Ort der tiefen Verehrung und ein Symbol für die Unabhängigkeit Marokkos, bewacht von der berittenen königlichen Garde in ihren prunkvollen Zeremonialuniformen.",
      hu: "A rabati V. Mohammed mauzóleum építészeti remekmű és Marokkó jelentős nemzeti emlékhelye. 1961 és 1971 között épült, és V. Mohammed király, valamint fiai, II. Haszan és Abdallah herceg sírjait őrzi. Az épületet Eric Vo Toan vietnami építész tervezte, ötvözve a hagyományos marokkói kézművességet a modern építési technikákkal. Külseje ragyogó fehér olasz márványból készült, tetejét pedig jellegzetes zöld cseréptető koronázza, amely az iszlám színe. Belső terében lenyűgöző az aranyfüsttel díszített cédrusfa kupola, a falakat pedig a legfinomabb zellige mozaikok borítják. A mauzóleum a befejezetlen Haszan-torony eszplanádján található, és azzal együtt monumentális együttest alkot. A mély tisztelet helye és Marokkó függetlenségének szimbóluma, amelyet a királyi gárda lovasai őriznek díszes ünnepi egyenruhában.",
      ro: "Mausoleul lui Mohammed al V-lea din Rabat este o capodoperă arhitecturală și un loc de comemorare națională semnificativ în Maroc. Construit între 1961 și 1971, adăpostește mormintele regelui Mohammed al V-lea și ale fiilor săi, Hassan al II-lea și prințul Abdallah. Edificiul a fost proiectat de arhitectul vietnamez Eric Vo Toan și combină măiestria tradițională marocană cu tehnici moderne de construcție. Exteriorul este realizat din marmură italiană albă strălucitoare și este încoronat de un acoperiș distinctiv din țiglă verde, culoarea islamului. În interior, impresionează cupola magnifică din lemn de cedru cu decorațiuni din foiță de aur, iar pereții sunt acoperiți cu cele mai fine mozaicuri zellige. Mausoleul se află pe esplanada Turnului Hassan neterminat și formează împreună cu acesta un ansamblu monumental. Este un loc de venerație profundă și un simbol al independenței Marocului, păzit de garda regală călare în uniformele lor ceremoniale somptuoase.",
      en: "The Mausoleum of Mohammed V in Rabat is an architectural masterpiece and a significant national memorial in Morocco. Constructed between 1961 and 1971, it houses the tombs of King Mohammed V and his sons, Hassan II and Prince Abdallah. The building was designed by Vietnamese architect Eric Vo Toan, combining traditional Moroccan craftsmanship with modern construction techniques. The exterior is crafted from brilliant white Italian marble and is crowned by a distinctive green tiled roof, the color of Islam. Inside, the magnificent cedar wood dome with gold leaf decorations is striking, and the walls are covered with the finest zellige mosaics. The mausoleum is located on the esplanade of the unfinished Hassan Tower, forming a monumental ensemble with it. It is a place of deep reverence and a symbol of Moroccan independence, guarded by the Royal Guard on horseback in their splendid ceremonial uniforms.",
      es: "El Mausoleo de Mohamed V en Rabat es uno de los monumentos modernos más importantes de Marruecos y una obra maestra de la arquitectura alauita. Alberga las tumbas del rey Mohamed V, quien llevó al país a la independencia en 1956, así como de sus dos hijos, el rey Hassan II y el príncipe Moulay Abdallah. El edificio, de radiante mármol blanco italiano, fue construido entre 1961 y 1971 y está coronado con un característico techo de tejas verdes, el color del Islam. En su interior, la cámara funeraria está magníficamente decorada con mosaicos de zellige, estuco artístico y un techo de madera de cedro y pan de oro. Los visitantes pueden observar desde una galería superior el elaborado sarcófago de ónice blanco. El mausoleo se encuentra en el mismo recinto que la Torre Hassan y simboliza la continuidad de la monarquía marroquí desde los almohades hasta hoy.",
      pt: "O Mausoléu de Mohammed V em Rabat é um dos monumentos modernos mais significativos de Marrocos e uma obra-prima da arquitetura alauita. Abriga os túmulos do rei marroquino Mohammed V, que conduziu o país à independência em 1956, bem como dos seus dois filhos, o rei Hassan II e o príncipe Moulay Abdallah. O edifício em mármore branco italiano radiante foi construído entre 1961 e 1971 e é coroado por um telhado de telhas verdes característico, a cor do Islão. No interior, a câmara funerária está magnificamente decorada com mosaicos de zellige, estuque artístico e um teto de madeira de cedro e folha de ouro. Os visitantes podem observar o sarcófago artístico em ónix branco a partir de uma galeria superior. O mausoléu situa-se no mesmo complexo que a Torre Hassan e simboliza a continuidade da monarquia marroquina desde os almoadas até aos dias de hoje.",
      fr: "Le mausolée de Mohammed V à Rabat est l'un des sites modernes les plus importants du Maroc et un chef-d'œuvre de l'architecture alaouite. Il abrite les tombeaux du roi Mohammed V, qui mena le pays à l'indépendance en 1956, ainsi que de ses deux fils, le roi Hassan II et le prince Moulay Abdallah. Le bâtiment en marbre blanc italien éclatant a été construit entre 1961 et 1971 et est surmonté d'un toit de tuiles vertes caractéristique, la couleur de l'Islam. À l'intérieur, la chambre funéraire est somptueusement ornée de mosaïques de zellige, de stucs travaillés et d'un plafond en bois de cèdre et feuilles d'or. Les visiteurs peuvent admirer le sarcophage élaboré en onyx blanc depuis une galerie supérieure. Le mausolée se trouve sur le même site que la tour Hassan et symbolise la continuité de la monarchie marocaine, des Almohades à nos jours.",
    },
