      hu: ["A mauzóleumot 1971. október 30-án avatták fel hivatalosan.", "Több mint 400 marokkói kézműves dolgozott a díszítésen.", "A zöld cseréptető az Alavita-házat szimbolizálja.", "V. Mohammedet a 'marokkói függetlenség atyjának' tekintik.", "A belépés muszlimok és nem muszlimok számára egyaránt ingyenes.", "Közvetlenül a 12. századi Haszan-toronnyal szemben áll."],
      ro: ["Mausoleul a fost inaugurat oficial pe 30 octombrie 1971.", "Peste 400 de meșteșugari marocani au lucrat la decorațiuni.", "Acoperișul de țiglă verde simbolizează dinastia Alaouită.", "Mohammed al V-lea este considerat 'tatăl independenței marocane'.", "Intrarea este gratuită atât pentru musulmani, cât și pentru non-musulmani.", "Se află direct vizavi de Turnul Hassan din secolul al XII-lea."],
      en: ["The mausoleum was officially inaugurated on October 30, 1971.", "Over 400 Moroccan artisans worked on the interior decoration.", "The green tiled roof symbolizes the ruling Alaouite dynasty.", "Mohammed V is considered the 'father of Moroccan independence'.", "Entry is free for both Muslims and non-Muslims alike.", "It stands directly opposite the 12th-century Hassan Tower."],
      es: ["La construcción duró 10 años, de 1961 a 1971.", "400 artesanos marroquíes participaron en la construcción.", "El diseño es obra del arquitecto vietnamita Eric Vo Toan.", "El rey Mohamed V es considerado el 'padre de la nación marroquí moderna'.", "El rey Hassan II, su sucesor, también fue enterrado aquí en 1999.", "El mausoleo está abierto a visitantes de todas las religiones.", "Guardias reales con uniformes tradicionales custodian la entrada.", "El complejo figura en la lista del Patrimonio Mundial de la UNESCO como parte de Rabat."],
      pt: ["A construção durou 10 anos, de 1961 a 1971.", "400 artesãos marroquinos participaram na construção.", "O design é do arquiteto vietnamita Eric Vo Toan.", "O rei Mohammed V é considerado o 'pai da moderna nação marroquina'.", "O rei Hassan II, o seu sucessor, também foi aqui sepultado em 1999.", "O mausoléu está aberto a visitantes de todas as religiões.", "Guardas reais em uniformes tradicionais vigiam a entrada.", "O complexo está na lista do Património Mundial da UNESCO como parte de Rabat."],
      fr: ["La construction a duré 10 ans, de 1961 à 1971.", "400 artisans marocains ont participé à la construction.", "Le design est l'œuvre de l'architecte vietnamien Eric Vo Toan.", "Le roi Mohammed V est considéré comme le 'père de la nation marocaine moderne'.", "Le roi Hassan II, son successeur, y a également été inhumé en 1999.", "Le mausolée est ouvert aux visiteurs de toutes confessions.", "Des gardes royaux en uniforme traditionnel surveillent l'entrée.", "Le complexe est inscrit au patrimoine mondial de l'UNESCO au titre de la ville de Rabat."],
